```javascript
const notes = new Map();
let counter = 0;

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'The note title. Must be non-empty.' },
          body: { type: 'string', description: 'The note body. Must be non-empty.' }
        },
        required: ['title', 'body']
      }
    },
    {
      name: 'note_get',
      description: 'Get a note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'The id of the note to retrieve.' }
        },
        required: ['note_id']
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    const title = args?.title;
    const body = args?.body;
    if (typeof title !== 'string' || title.trim() === '') throw new Error('title is required and must be non-empty');
    if (typeof body !== 'string' || body.trim() === '') throw new Error('body is required and must be non-empty');
    const id = 'n' + (++counter);
    notes.set(id, { id, title, body });
    return { content: [{ type: 'text', text: `Created note ${id}: ${title}` }] };
  }
  if (name === 'note_get') {
    const note_id = args?.note_id;
    if (typeof note_id !== 'string' || note_id.trim() === '') throw new Error('note_id is required');
    const note = notes.get(note_id);
    if (!note) throw new Error(`note ${note_id} not found`);
    return { content: [{ type: 'text', text: `${note.title}\n\n${note.body}` }] };
  }
  throw new Error(`unknown tool: ${name}`);
}
